// Deduplicate removes duplicate strings from the input slice while
// preserving the order of first occurrence. The original slice is not modified.
func Deduplicate(input []string) []string {
	seen := make(map[string]bool)
	result := make([]string, 0, len(input))

	for _, str := range input {
		if !seen[str] {
			seen[str] = true
			result = append(result, str)
		}
	}

	return result
}

