// Node represents a single element in the linked list
type Node struct {
	value int
	next  *Node
}

// LinkedList is a singly linked list that stores integers.
// It supports inserting values at the end and converting to a slice.
type LinkedList struct {
	head *Node
	tail *Node
	size int
}

// Insert adds a new value to the end of the linked list.
func (l *LinkedList) Insert(value int) {
	newNode := &Node{value: value}
	if l.head == nil {
		l.head = newNode
		l.tail = newNode
	} else {
		l.tail.next = newNode
		l.tail = newNode
	}
	l.size++
}

// ToSlice converts the linked list to a slice of integers in order.
func (l *LinkedList) ToSlice() []int {
	result := make([]int, 0, l.size)
	current := l.head
	for current != nil {
		result = append(result, current.value)
		current = current.next
	}
	return result
}

