Here's a simple in-memory pub/sub class implementation in TypeScript:

```typescript
/**
 * A simple in-memory pub/sub (publish/subscribe) event system.
 * Allows multiple subscribers to listen for events and receive published data.
 */
class PubSub {
  // Map to store event names and their associated callback functions
  private events: Map<string, Array<(data: any) => void>> = new Map();

  /**
   * Subscribe to an event with a callback function
   * @param event - The event name to subscribe to
   * @param callback - Function to be called when the event is published
   * @returns An unsubscribe function to remove the subscription
   */
  subscribe(event: string, callback: (data: any) => void): () => void {
    // Get existing subscribers for this event, or create a new array
    const subscribers = this.events.get(event) || [];

    // Add the new callback to the subscribers list
    subscribers.push(callback);

    // Store the updated subscribers list
    this.events.set(event, subscribers);

    // Return an unsubscribe function for easy cleanup
    return () => {
      const currentSubscribers = this.events.get(event);
      if (currentSubscribers) {
        // Filter out the callback we want to remove
        this.events.set(
          event,
          currentSubscribers.filter(sub => sub !== callback)
        );
      }
    };
  }

  /**
   * Publish an event with data to all subscribers
   * @param event - The event name to publish
   * @param data - Data to pass to all subscriber callbacks
   */
  publish(event: string, data: any): void {
    // Get all subscribers for this event
    const subscribers = this.events.get(event);

    // If there are subscribers, call each one with the data
    if (subscribers) {
      subscribers.forEach(callback => {
        callback(data);
      });
    }
  }
}

// Example usage with two subscribers receiving the same event
const pubSub = new PubSub();

// Subscriber 1
const unsubscribe1 = pubSub.subscribe('userLogin', (data) => {
  console.log(`Subscriber 1: User ${data.username} logged in at ${data.timestamp}`);
});

// Subscriber 2
const unsubscribe2 = pubSub.subscribe('userLogin', (data) => {
  console.log(`Subscriber 2: Welcome ${data.username}! Login time: ${data.timestamp}`);
});

// Publish the event - both subscribers will receive it
pubSub.publish('userLogin', {
  username: 'john_doe',
  timestamp: new Date().toISOString()
});

// Output:
// Subscriber 1: User john_doe logged in at 2024-01-15T10:30:00.000Z
// Subscriber 2: Welcome john_doe! Login time: 2024-01-15T10:30:00.000Z

// Optional: Unsubscribe when no longer needed
// unsubscribe1();
// unsubscribe2();
```

**Key Features:**
- **Type Safety**: Uses TypeScript type annotations for parameters and return types
- **Unsubscribe Function**: Each subscription returns a cleanup function
- **Multiple Subscribers**: Supports multiple subscribers for the same event

Here's a Go function that checks for anagrams while ignoring case and spaces:

```go
// AreAnagrams checks whether two strings are anagrams of each other,
// ignoring case and spaces. It uses a frequency map to count character
// occurrences after normalizing both strings to lowercase and removing
// all whitespace. The function returns true if both strings contain
// the same characters with the same frequencies.
//
// Example:
//
//	result := AreAnagrams("Listen", "Silent")
//	fmt.Println(result) // Output: true
func AreAnagrams(s1, s2 string) bool {
	// Normalize strings: convert to lowercase and remove spaces
	normalized1 := normalize(s1)
	normalized2 := normalize(s2)

	// If lengths differ after normalization, they can't be anagrams
	if len(normalized1) != len(normalized2) {
		return false
	}

	// Count character frequencies in first string
	charCount := make(map[rune]int)
	for _, char := range normalized1 {
		charCount[char]++
	}

	// Decrement frequencies for second string
	for _, char := range normalized2 {
		charCount[char]--
		if charCount[char] < 0 {
			return false
		}
	}

	// All counts should be zero if strings are anagrams
	for _, count := range charCount {
		if count != 0 {
			return false
		}
	}

	return true
}

// normalize converts a string to lowercase and removes all whitespace
func normalize(s string) string {
	var builder strings.Builder
	for _, char := range strings.ToLower(s) {
		if !unicode.IsSpace(char) {
			builder.WriteRune(char)
		}
	}
	return builder.String()
}
```

**Example usage:**
```go
package main

import (
	"fmt"
	"strings"
	"unicode"
)

func main() {
	// Test cases
	fmt.Println(AreAnagrams("Listen", "Silent"))       // true
	fmt.Println(AreAnagrams("Hello World", "World Hello")) // true
	fmt.Println(AreAnagrams("Dormitory", "Dirty room"))   // true
	fmt.Println(AreAnagrams("Hello", "World"))          // false
	fmt.Println(AreAnagrams("", ""))                    // true
}
```

**Key points about the implementation:**

1. **Normalization**: The `normalize` function converts strings to lowercase and removes all whitespace characters (spaces, tabs, newlines, etc.)
2. **Frequency counting**: Uses a map to count character occurrences in the first string, then decrements for the second string
3. **Early exit**: Returns `false` immediately if lengths differ after normalization
4. **Efficiency**: O(n) time complexity where n is the length of the strings
5. **Unicode support**: Works with Unicode characters, not just ASCII

Here's a JavaScript function that deep-clones plain objects and arrays without using JSON methods:

```javascript
/**
 * Deep clones a plain object or array
 * @param {Object|Array} obj - The object/array to clone
 * @returns {Object|Array} - A deep clone
 * 
 * LIMITATION: This function only handles plain objects, arrays, and primitive values.
 * It does NOT handle: functions, Date objects, RegExp, Map, Set, circular references,
 * or special objects with custom prototypes.
 */
function deepClone(obj) {
  // Handle primitive types and null
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  // Create a new container based on whether it's an array or object
  const clone = Array.isArray(obj) ? [] : {};

  // Recursively copy each property
  for (let key in obj) {
    // Only copy own enumerable properties (not inherited)
    if (obj.hasOwnProperty(key)) {
      clone[key] = deepClone(obj[key]);
    }
  }

  return clone;
}

// Example with nested object
const original = {
  name: "John",
  age: 30,
  address: {
    street: "123 Main St",
    city: "New York",
    coordinates: {
      lat: 40.7128,
      lng: -74.0060
    }
  },
  hobbies: ["reading", "coding", "hiking"],
  nestedArray: [
    { id: 1, tags: ["a", "b"] },
    { id: 2, tags: ["c", "d"] }
  ]
};

const cloned = deepClone(original);

// Test the clone
console.log("Original:", original);
console.log("Clone:", cloned);

// Verify they're independent
cloned.address.city = "Los Angeles";
cloned.hobbies.push("swimming");
cloned.nestedArray[0].tags.push("z");

console.log("\nAfter modifying clone:");
console.log("Original city:", original.address.city); // Still "New York"
console.log("Clone city:", cloned.address.city); // "Los Angeles"
console.log("Original hobbies:", original.hobbies); // ["reading", "coding", "hiking"]
console.log("Clone hobbies:", cloned.hobbies); // ["reading", "coding", "hiking", "swimming"]
console.log("Original nested tags:", original.nestedArray[0].tags); // ["a", "b"]
console.log("Clone nested tags:", cloned.nestedArray[0].tags); // ["a", "b", "z"]

// Verify they're not the same reference
console.log("\nAre they the same object?", original === cloned); // false
console.log("Are nested objects the same?", original.address === cloned.address); // false
```

**Key points about the implementation:**

1. **Recursive approach**: The function calls itself for each nested object/array
2. **Type detection**: Uses `Array.isArray()` to distinguish arrays from objects
3. **Own properties only**: Uses `hasOwnProperty()` to avoid copying inherited properties
4. **Primitive handling**: Returns primitives and null as-is

**Limitations:**
- Doesn't handle functions, Date, RegExp, Map, Set, or other special objects

