```go
package main

import "fmt"

// Node represents a single element in the linked list
type Node struct {
    value int
    next  *Node
}

// LinkedList is a singly linked list that stores integers.
// It supports insertion at the end and conversion to a slice.
type LinkedList struct {
    head *Node
    tail *Node
}

// Insert adds a new value to the end of the linked list.
func (l *LinkedList) Insert(value int) {
    newNode := &Node{value: value}

    if l.head == nil {
        l.head = newNode
        l.tail = newNode
        return
    }

    l.tail.next = newNode
    l.tail = newNode
}

// ToSlice converts the linked list to a slice of integers.
// It returns an empty slice if the list is empty.
func (l *LinkedList) ToSlice() []int {
    result := []int{}
    current := l.head

    for current != nil {
        result = append(result, current.value)
        current = current.next
    }

    return result
}

// Example usage:
// list := &LinkedList{}
// list.Insert(1)
// list.Insert(2)
// list.Insert(3)
// fmt.Println(list.ToSlice()) // Output: [1 2 3]

func main() {
    // Example usage
    list := &LinkedList{}
    list.Insert(1)
    list.Insert(2)
    list.Insert(3)
    fmt.Println(list.ToSlice()) // Output: [1 2 3]
}
```

**Key features:**

1. **`Node` struct**: Represents each element with a value and pointer to the next node
2. **`LinkedList` struct**: Maintains both head and tail pointers for efficient O(1) insertion at the end
3. **`Insert(value int)`**: Adds a new node at the end of the list
4. **`ToSlice() []int`**: Traverses the list and returns all values as a slice

**Time complexity:**
- Insert: O(1) - using tail pointer
- ToSlice: O(n) - must traverse all nodes

**Space complexity:** O(n) for storing n elements

